"use client"

import * as React from "react"

import { useInk } from "@/lib/ink/react"
import { tableSurfaceRecipe } from "@/lib/ink/recipes/table-ink"
import { cn } from "@/lib/utils"

function Table({
  className,
  seed,
  ref,
  ...props
}: React.ComponentProps<"table"> & { seed?: string | number }) {
  const { hostRef, hostProps, node } = useInk({
    recipe: tableSurfaceRecipe,
    params: {},
    kind: "table",
    seed,
    still: true,
  })

  return (
    <div data-slot="table-container" className="relative w-full overflow-x-auto rounded-[var(--radius-md)]">
      <div
        ref={hostRef}
        {...hostProps}
        className="pointer-events-none absolute inset-0 overflow-hidden rounded-[var(--radius-md)]"
        aria-hidden
      >
        {node}
      </div>
      <table
        ref={ref}
        data-slot="table"
        className={cn("relative z-[1] w-full caption-bottom text-sm", className)}
        {...props}
      />
    </div>
  )
}

function TableHeader({ className, ...props }: React.ComponentProps<"thead">) {
  return <thead data-slot="table-header" className={cn("[&_tr]:border-b-0", className)} {...props} />
}

function TableBody({ className, ...props }: React.ComponentProps<"tbody">) {
  return <tbody data-slot="table-body" className={cn("[&_tr:last-child]:border-0", className)} {...props} />
}

function TableFooter({ className, ...props }: React.ComponentProps<"tfoot">) {
  return (
    <tfoot
      data-slot="table-footer"
      className={cn("border-t border-[color-mix(in_srgb,var(--sd-ink)_8%,transparent)] font-medium", className)}
      {...props}
    />
  )
}

function TableRow({ className, ...props }: React.ComponentProps<"tr">) {
  return (
    <tr
      data-slot="table-row"
      className={cn(
        "border-b border-[color-mix(in_srgb,var(--sd-ink)_6%,transparent)] transition-colors",
        "hover:bg-[color-mix(in_srgb,var(--sd-rose-wash)_12%,transparent)] data-[state=selected]:bg-[color-mix(in_srgb,var(--sd-rose-wash)_18%,transparent)]",
        className,
      )}
      {...props}
    />
  )
}

function TableHead({ className, ...props }: React.ComponentProps<"th">) {
  return (
    <th
      data-slot="table-head"
      className={cn(
        "h-10 px-3 text-start align-middle text-xs font-semibold tracking-wide text-muted-foreground uppercase",
        "[&:has([role=checkbox])]:pe-0",
        className,
      )}
      {...props}
    />
  )
}

function TableCell({ className, ...props }: React.ComponentProps<"td">) {
  return (
    <td
      data-slot="table-cell"
      className={cn("px-3 py-2.5 align-middle text-foreground [&:has([role=checkbox])]:pe-0", className)}
      {...props}
    />
  )
}

function TableCaption({ className, ...props }: React.ComponentProps<"caption">) {
  return (
    <caption
      data-slot="table-caption"
      className={cn("relative z-[1] mt-4 text-sm text-muted-foreground", className)}
      {...props}
    />
  )
}

export { Table, TableBody, TableCaption, TableCell, TableFooter, TableHead, TableHeader, TableRow }

import { roundRectPoly } from '@/lib/ink/geom'
import { box, line } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import { defineRecipe } from '@/lib/ink/recipes'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export const tableSurfaceRecipe = defineRecipe<Record<string, never>>({
  id: 'table-surface',
  kind: 'table',
  layers: ['rest'],
  pad: 8,
  draw(ink, { w, h }) {
    const r = clamp(Math.min(w, h) * 0.025, 4, 8)
    const inset = 0.6
    const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)
    const pitch = clamp(h / 8, 32, 44)

    ink.layer('rest', () => {
      softFill(ink, body, [
        { color: 'sand-slip', alpha: 0.72, wobble: 0.45 },
        { color: 'sand', alpha: 0.26, inset: 1, wobble: 0.5 },
      ])
      box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
        pen: 'pencil.fine',
        corner: r,
        loose: 0.85,
        opts: { alpha: 0.48, simple: w > 420, color: 'ink-soft' },
      })
      for (let y = pitch; y < h - pitch * 0.45; y += pitch) {
        line(ink, 6, y, w - 6, y, {
          pen: 'pencil.fine',
          loose: 0.5,
          opts: { alpha: 0.28, simple: w > 360, color: 'line-soft' },
        })
        line(ink, 8, y + 0.55, w - 8, y + 0.55, {
          pen: 'horizonPencil.fine',
          loose: 0.42,
          opts: { alpha: 0.18, simple: w > 360 },
        })
      }
    })
  },
})

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
